using System;using System.IO;using System.Xml;using System.Collections.Generic;using System.Reflection;using System.Runtime.Serialization;using UnityEngine;using Delve;using DelveBatchTen;
public class ConsoleCmdBatchTen:ConsoleCmdAbstract {
 static int checks;static void Check(bool b,string m){checks++;if(!b)throw new Exception(m);}
 public override string[] getCommands(){return new[]{"batch10verify"};}public override string getDescription(){return "Current batch automated station, nutrition, healing, harvesting and save checks.";}
 public override void Execute(List<string> args,CommandSenderInfo sender){var entities=new List<EntityAlive>();bool old=XUiM_Recipes.WorkstationCrafting;var backpack=XUiM_Recipes.BackpackCrafting;try{checks=0;XUiM_Recipes.WorkstationCrafting=true;XUiM_Recipes.BackpackCrafting=(BackpackCraftingOptions)1;var world=GameManager.Instance.World;
  for(int j=0;j<5;j++){var p=EntityFactory.CreateEntity(EntityClass.FromString("playerMale"),new Vector3(j==0?0:j==1?.5f:j==2?1:1.01f,100,0)) as EntityAlive;p.world=world;p.Health=10;entities.Add(p);}
  var player=entities[0];var all=CraftingManager.GetAllRecipes();var byKey=new Dictionary<string,Recipe>();foreach(var r in all)byKey[ForestSliceCatalog.Key(r)]=r;
  var inv=XUiM_Recipes.FilterRecipesByWorkstation("",all);var doc=new XmlDocument();doc.Load(Path.Combine(ModManager.GetMod("StationProbe",true).Path,"batch10.xml"));int routes=0;
  foreach(XmlElement e in doc.SelectNodes("/batch/route")){Recipe r;Check(byKey.TryGetValue(e.GetAttribute("key"),out r),"Exact recipe "+e.GetAttribute("key"));int rank=int.Parse(e.GetAttribute("rank"));string skill=e.GetAttribute("skill");Check(!inv.Contains(r),"Inventory exclusion "+r.GetName());Check(XUiM_Recipes.FilterRecipesByWorkstation(e.GetAttribute("station"),all).Contains(r),"Correct station "+r.GetName());Check(r.craftingToolType==0,"No circular installed-tool dependency "+r.GetName());CharacterProgression.Set(player,"delvePractice"+skill,ProficiencyRules.Threshold(rank));Check(RecipeProgression.Allowed(r,player)&&r.IsUnlocked((EntityPlayer)player),"Rank access "+r.GetName());if(rank>1){CharacterProgression.Set(player,"delvePractice"+skill,ProficiencyRules.Threshold(rank-1));Check(!RecipeProgression.Allowed(r,player),"Rank boundary "+r.GetName());}
   var station=new TileEntityWorkstation((Chunk)null);station.SetDisableModifiedCheck(true);station.Queue=new[]{new RecipeQueueItem{Recipe=r,Multiplier=1,CraftingTimeLeft=0,OneItemCraftTime=1,Quality=1,StartingEntityId=-1}};typeof(TileEntityWorkstation).GetMethod("HandleRecipeQueue",BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic).Invoke(station,new object[]{2f});int output=0;foreach(var s in station.Output)if(s.itemValue.type==r.itemValueType)output+=s.count;Check(output==r.count,"Native queue "+r.GetName());routes++;
  }
  foreach(var r in all)if(r.GetName().StartsWith("delveUpgrade")||r.GetName()=="delveWandRune"||r.GetName()=="delveStaffRune"||r.GetName()=="delveTotemRune"||r.GetName()=="delveHealingRune")Check(!string.IsNullOrEmpty(r.craftingArea),"No alternate inventory bypass "+r.GetName());
  foreach(XmlElement e in doc.SelectNodes("/batch/crate")){var b=Block.GetBlockValue(e.GetAttribute("name"),false).Block;Check(b.Properties.GetString("ModelOffset")=="0,0,0","Crate ground offset "+b.GetBlockName());}
  var berries=ItemClass.GetItem("foodDelveCookedBerries",false);var eat=berries.ItemClass.Actions[0] as ItemActionEat;Check(eat!=null&&eat.CreateItemCount==0&&!eat.UseJarRefund,"Cooked berry no jar path");foreach(string v in new[]{"$foodAmountAdd","$waterAmountAdd","$healthAmountAdd"})player.Buffs.SetCustomVar(v,0);int hp=player.Health;berries.ItemClass.FireEvent(MinEventTypes.onSelfPrimaryActionEnd,new MinEventParams{Self=player,ItemValue=berries});Check(player.Buffs.GetCustomVar("$foodAmountAdd")==5&&player.Buffs.GetCustomVar("$waterAmountAdd")==5&&player.Health==hp,"Cooked berry 5/5/0");
  entities[2].Health=entities[2].GetMaxHealth()-5;int cap=entities[2].Health;var targets=new List<EntityAlive>{entities[0],entities[1],entities[2],entities[3],entities[0]};Check(HealingTotem.PulseTargets(player,20,targets)==3,"Pulse self, allies, radius and deduplication");foreach(var target in targets)target.Buffs.Tick();SdtdConsole.Instance.Output("HEAL RESULTS "+player.Health+","+entities[1].Health+","+entities[2].Health+","+entities[3].Health+" cap="+cap);Check(player.Health==30&&entities[1].Health==30&&entities[2].Health==cap+5&&entities[3].Health==10,"Actual native healing and cap");entities[4].Health=0;Check(!HealingTotem.InPulse(player,entities[4]),"Dead player excluded");
  for(int q=1;q<=6;q++){CharacterProgression.Set(player,"delvePracticeFarming",ProficiencyRules.Threshold(q==1?1:(q-1)*4));Check(EffectManager.GetValue(PassiveEffects.CraftingTier,ItemClass.GetItem("delveHarvestScythe",false),1,player)==q,"Native scythe crafting quality "+q);float carry=0;int total=0;for(int j=0;j<100;j++)total+=FirstTierRules.Yield(1,ref carry,Scythe.Bonus(q));Check(Math.Abs(total-(100+(q-1)*10))<=1,"Quality yield "+q);}Check(!FirstTierHarvest.Raw("plantedDelveBramble1")&&!FirstTierHarvest.Raw("seedCotton"),"Seeds excluded");Check(Scythe.InArc(Vector3.forward,new Vector3(1,0,1.5f))&&Scythe.InArc(Vector3.forward,new Vector3(-1,0,1.5f))&&!Scythe.InArc(Vector3.forward,Vector3.back)&&!Scythe.InArc(Vector3.forward,new Vector3(2,0,1)),"Forward multi-cell arc");Check(Scythe.Eligible(Block.GetBlockValue("plantedDelveBramble3Harvest",false))&&!Scythe.Eligible(Block.GetBlockValue("plantedDelveBramble1",false))&&!Scythe.Eligible(Block.GetBlockValue("terrDirt",false)),"Mature-only harvesting");
  var state=(ItemActionRanged.ItemActionDataRanged)FormatterServices.GetUninitializedObject(typeof(ItemActionRanged.ItemActionDataRanged));Check(!Magic.Reloading(state),"Idle glow off");state.isReloadRequested=true;Check(Magic.Reloading(state),"Requested glow on");state.isReloadRequested=false;state.isReloading=true;Check(Magic.Reloading(state),"Reload glow on");state.isReloading=false;Check(!Magic.Reloading(state),"Complete/cancel glow off");Check(Magic.ColorFor("heal").g>Magic.ColorFor("heal").r&&Magic.ColorFor("hex").b>Magic.ColorFor("hex").g,"Green and purple totems");
  var manager=(RegionFileManager)typeof(ChunkProviderGenerateWorld).GetField("m_RegionFileManager",BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public).GetValue(world.ChunkCache.ChunkProvider);int chunks=0;foreach(long k in manager.GetAllChunkKeys()){Check(manager.GetChunkSync(k)!=null,"Saved chunk loads");chunks++;}
  SdtdConsole.Instance.Output("[Batch10] PASS "+checks+" checks; "+routes+" routed native queues; no inventory/tool circular bypass; crate offsets; berry jar suppression; native self/ally healing; scythe arc/yield boundaries; reload states; "+chunks+" saved chunks.");
 }catch(Exception e){SdtdConsole.Instance.Output("[Batch10] FAIL "+e);}finally{XUiM_Recipes.WorkstationCrafting=old;XUiM_Recipes.BackpackCrafting=backpack;foreach(var p in entities)if(p!=null)UnityEngine.Object.Destroy(p.gameObject);}}
}


